"""
Telegram Join/Exit Analytics Tracker
------------------------------------
- Telegram bot (webhook) jo group me join/exit events sunta hai
- Har join ko uske invite-link ke naam (= campaign / helper) se jodta hai
- SQLite database me sab store karta hai
- Ek password-protected dashboard dikhata hai (video jaisa)

Env variables (Railway me set karne hain):
  BOT_TOKEN           -> @BotFather se mila token (zaroori)
  DASHBOARD_PASSWORD  -> dashboard kholne ka password (zaroori)
  SECRET_KEY          -> koi bhi random lamba string (zaroori)
  PUBLIC_URL          -> Railway apne aap de deta hai; warna khud daal do
"""

import os
import json
import time
import sqlite3
import threading
import datetime
from zoneinfo import ZoneInfo

import requests
from flask import (Flask, request, session, redirect, url_for,
                   render_template, jsonify, abort)

# ---------------- CONFIG ----------------
BOT_TOKEN = os.environ.get("BOT_TOKEN", "")
DASHBOARD_PASSWORD = os.environ.get("DASHBOARD_PASSWORD", "changeme")
SECRET_KEY = os.environ.get("SECRET_KEY", "please-change-this-secret")
# Railway apne aap ye URL de deta hai:
PUBLIC_URL = (os.environ.get("PUBLIC_URL")
              or os.environ.get("RAILWAY_PUBLIC_DOMAIN")
              or "").strip()
if PUBLIC_URL and not PUBLIC_URL.startswith("http"):
    PUBLIC_URL = "https://" + PUBLIC_URL

IST = ZoneInfo("Asia/Kolkata")
API = f"https://api.telegram.org/bot{BOT_TOKEN}"
DB_PATH = os.environ.get("DB_PATH", "data.db")

app = Flask(__name__)
app.secret_key = SECRET_KEY

# ---------- EMBEDDED PAGES (phone-friendly single-file build) ----------
import base64 as _b64
DASHBOARD_HTML = _b64.b64decode("").decode("utf-8")
LOGIN_HTML = _b64.b64decode("").decode("utf-8")


_db_lock = threading.Lock()


# ---------------- DATABASE ----------------
def db():
    conn = sqlite3.connect(DB_PATH, check_same_thread=False)
    conn.row_factory = sqlite3.Row
    return conn


def init_db():
    with _db_lock, db() as c:
        c.execute("""
            CREATE TABLE IF NOT EXISTS events (
                id         INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id    INTEGER,
                username   TEXT,           -- joiner ka @username (bina @)
                name       TEXT,           -- joiner ka naam
                event_type TEXT,           -- 'join' or 'exit'
                campaign   TEXT,           -- invite link ka naam (helper/campaign)
                link_url   TEXT,           -- actual invite link URL
                approval   INTEGER,        -- 1 agar join approval zaroori
                group_id   INTEGER,
                group_name TEXT,
                ts         INTEGER          -- UTC epoch seconds
            )
        """)
        c.execute("CREATE INDEX IF NOT EXISTS idx_ts ON events(ts)")
        c.execute("CREATE INDEX IF NOT EXISTS idx_campaign ON events(campaign)")
        c.execute("CREATE INDEX IF NOT EXISTS idx_user ON events(user_id)")
        # Purane database ke liye migration (naye columns add karo agar nahi hain)
        for col in ("username TEXT", "name TEXT"):
            try:
                c.execute(f"ALTER TABLE events ADD COLUMN {col}")
            except Exception:
                pass


def log_event(user_id, username, name, event_type, campaign, link_url,
              approval, group_id, group_name):
    with _db_lock, db() as c:
        c.execute(
            "INSERT INTO events (user_id,username,name,event_type,campaign,"
            "link_url,approval,group_id,group_name,ts) "
            "VALUES (?,?,?,?,?,?,?,?,?,?)",
            (user_id, username or "", name or "", event_type,
             campaign or "Direct / Unknown", link_url or "",
             1 if approval else 0, group_id, group_name, int(time.time()))
        )


# ---------------- TELEGRAM WEBHOOK ----------------
JOINED = {"member", "administrator", "creator"}
LEFT = {"left", "kicked"}


@app.route("/webhook", methods=["POST"])
def webhook():
    update = request.get_json(force=True, silent=True) or {}
    cm = update.get("chat_member") or update.get("my_chat_member")
    if cm:
        handle_chat_member(cm)
    return "ok"


def handle_chat_member(cm):
    try:
        chat = cm.get("chat", {})
        group_id = chat.get("id")
        group_name = chat.get("title") or "Unknown Group"
        user = (cm.get("new_chat_member") or {}).get("user", {})
        user_id = user.get("id")
        username = user.get("username") or ""          # bina @
        name = (user.get("first_name", "") + " " +
                user.get("last_name", "")).strip()
        old_status = (cm.get("old_chat_member") or {}).get("status")
        new_status = (cm.get("new_chat_member") or {}).get("status")

        invite = cm.get("invite_link") or {}
        campaign = invite.get("name") or ""           # link ka naam = campaign/helper
        link_url = invite.get("invite_link") or ""    # actual URL
        approval = invite.get("creates_join_request", False)  # approval zaroori?

        # JOIN: pehle member nahi tha, ab member ban gaya
        if old_status not in JOINED and new_status in JOINED:
            log_event(user_id, username, name, "join", campaign, link_url,
                      approval, group_id, group_name)
        # EXIT: pehle member tha, ab chala gaya.
        # User kis link se aaya tha wo uske last join se pata karte hain,
        # taaki exit sahi helper/campaign ke neeche count ho.
        elif old_status in JOINED and new_status in LEFT:
            prev_campaign, prev_url = last_join_of(user_id, group_id)
            log_event(user_id, username, name, "exit", prev_campaign,
                      prev_url, False, group_id, group_name)
    except Exception as e:
        print("handle_chat_member error:", e)


def last_join_of(user_id, group_id):
    """User ne pichhli baar kis campaign/link se join kiya tha."""
    with _db_lock, db() as c:
        row = c.execute(
            "SELECT campaign,link_url FROM events "
            "WHERE user_id=? AND group_id=? AND event_type='join' "
            "ORDER BY ts DESC LIMIT 1", (user_id, group_id)).fetchone()
    if row:
        return row["campaign"], row["link_url"]
    return "", ""


def setup_webhook():
    """App start hone par Telegram ko webhook URL bata deta hai."""
    if not BOT_TOKEN or not PUBLIC_URL:
        print("[WARN] BOT_TOKEN ya PUBLIC_URL missing - webhook set nahi hua")
        return
    url = f"{PUBLIC_URL}/webhook"
    try:
        r = requests.post(f"{API}/setWebhook", json={
            "url": url,
            # chat_member updates ke liye ye zaroori hai:
            "allowed_updates": ["message", "chat_member", "my_chat_member"]
        }, timeout=15)
        print("setWebhook:", r.json())
    except Exception as e:
        print("setWebhook error:", e)


# ---------------- TIME RANGES (8PM IST reset) ----------------
def last_8pm(ref):
    anchor = ref.replace(hour=20, minute=0, second=0, microsecond=0)
    if ref < anchor:
        anchor -= datetime.timedelta(days=1)
    return anchor


def range_bounds(key):
    now = datetime.datetime.now(IST)
    if key == "today":
        start, end = last_8pm(now), now
    elif key == "yesterday":
        end = last_8pm(now)
        start = end - datetime.timedelta(days=1)
    elif key == "7days":
        start, end = now - datetime.timedelta(days=7), now
    elif key == "30days":
        start, end = now - datetime.timedelta(days=30), now
    else:  # all / alltime
        start = datetime.datetime(2000, 1, 1, tzinfo=IST)
        end = now
    return int(start.timestamp()), int(end.timestamp()), key


# ---------------- AUTH ----------------
def logged_in():
    return session.get("ok") is True


@app.before_request
def guard():
    open_paths = {"/login", "/webhook", "/health"}
    if request.path in open_paths or request.path.startswith("/static"):
        return
    if not logged_in():
        if request.path.startswith("/api"):
            return jsonify({"error": "auth"}), 401
        return redirect(url_for("login"))


@app.route("/login", methods=["GET", "POST"])
def login():
    if request.method == "POST":
        pw = (request.form.get("password") or "").strip()
        if pw == DASHBOARD_PASSWORD:
            session["ok"] = True
            return redirect(url_for("dashboard"))
        return LOGIN_HTML.replace("__ERROR__", "Incorrect password")
    return LOGIN_HTML.replace("__ERROR__", "")


@app.route("/logout")
def logout():
    session.clear()
    return redirect(url_for("login"))


# ---------------- PAGES ----------------
@app.route("/")
def dashboard():
    return DASHBOARD_HTML


@app.route("/health")
def health():
    return "ok"


# ---------------- API ----------------
@app.route("/api/filters")
def api_filters():
    with _db_lock, db() as c:
        groups = [r["group_name"] for r in c.execute(
            "SELECT DISTINCT group_name FROM events WHERE group_name IS NOT NULL")]
        camps = [r["campaign"] for r in c.execute(
            "SELECT DISTINCT campaign FROM events "
            "WHERE event_type='join' AND campaign IS NOT NULL ORDER BY campaign")]
    return jsonify({"groups": groups, "campaigns": camps})


@app.route("/api/stats")
def api_stats():
    rng = request.args.get("range", "today")
    group = request.args.get("group", "")
    camp = request.args.get("campaign", "")
    start, end, key = range_bounds(rng)

    where = ["ts BETWEEN ? AND ?"]
    params = [start, end]
    if group and group != "All Groups":
        where.append("group_name = ?")
        params.append(group)
    if camp and camp != "All Usernames":
        where.append("campaign = ?")
        params.append(camp)
    wsql = " AND ".join(where)

    with _db_lock, db() as c:
        rows = c.execute(
            f"SELECT user_id,event_type,campaign,link_url,approval,ts "
            f"FROM events WHERE {wsql}",
            params).fetchall()

    total_joins = sum(1 for r in rows if r["event_type"] == "join")
    total_exits = sum(1 for r in rows if r["event_type"] == "exit")
    unique_joins = len({r["user_id"] for r in rows if r["event_type"] == "join"})

    # ---- per-campaign (helper) breakdown ----
    helpers = {}
    for r in rows:
        name = r["campaign"] or "Direct / Unknown"
        h = helpers.setdefault(name, {"name": name, "joins": 0,
                                      "uids": set(), "exits": 0, "last": 0})
        if r["event_type"] == "join":
            h["joins"] += 1
            h["uids"].add(r["user_id"])
            h["last"] = max(h["last"], r["ts"])
        else:
            h["exits"] += 1
    helper_list = []
    for h in helpers.values():
        helper_list.append({
            "name": h["name"], "joins": h["joins"],
            "unique": len(h["uids"]), "exits": h["exits"],
            "last_ago": ago(h["last"])
        })
    helper_list.sort(key=lambda x: x["joins"], reverse=True)

    # ---- chart buckets ----
    labels, j_series, e_series = build_chart(rows, key)

    return jsonify({
        "totals": {"joins": total_joins, "unique": unique_joins, "exits": total_exits},
        "chart": {"labels": labels, "joins": j_series, "exits": e_series},
        "helpers": helper_list
    })


@app.route("/api/members")
def api_members():
    """Har aane wale member ki list: @username, source, kab aaya, abhi hai ya nahi."""
    rng = request.args.get("range", "today")
    group = request.args.get("group", "")
    camp = request.args.get("campaign", "")
    limit = min(int(request.args.get("limit", 300)), 1000)
    start, end, key = range_bounds(rng)

    where = ["ts BETWEEN ? AND ?"]
    params = [start, end]
    if group and group != "All Groups" and group != "All groups":
        where.append("group_name = ?")
        params.append(group)
    if camp and camp not in ("All Usernames", "All sources"):
        where.append("campaign = ?")
        params.append(camp)
    wsql = " AND ".join(where)

    with _db_lock, db() as c:
        rows = c.execute(
            f"SELECT user_id,username,name,event_type,campaign,ts "
            f"FROM events WHERE {wsql} ORDER BY ts ASC", params).fetchall()

    members = {}
    for r in rows:
        uid = r["user_id"]
        m = members.get(uid)
        if not m:
            m = members[uid] = {"user_id": uid, "username": "", "name": "",
                                "source": "", "join_ts": 0, "last_ts": 0,
                                "status": "left"}
        if r["username"]:
            m["username"] = r["username"]
        if r["name"]:
            m["name"] = r["name"]
        if r["ts"] >= m["last_ts"]:
            m["last_ts"] = r["ts"]
            m["status"] = "in" if r["event_type"] == "join" else "left"
        if r["event_type"] == "join" and r["ts"] >= m["join_ts"]:
            m["join_ts"] = r["ts"]
            m["source"] = r["campaign"]

    out = []
    for m in members.values():
        if not m["join_ts"]:
            continue  # sirf exit dikha, join range me nahi — skip
        label = ("@" + m["username"]) if m["username"] else (m["name"] or f"User {m['user_id']}")
        out.append({
            "label": label,
            "has_username": bool(m["username"]),
            "source": m["source"] or "Direct / Unknown",
            "when": full_date(m["join_ts"]),
            "ago": ago(m["join_ts"]),
            "status": m["status"],
            "ts": m["join_ts"]
        })
    out.sort(key=lambda x: x["ts"], reverse=True)
    total = len(out)
    return jsonify({"total": total, "members": out[:limit]})


@app.route("/api/helper")
def api_helper():
    """Ek helper/campaign ki poori detail + uske links (popup ke liye)."""
    name = request.args.get("name", "")
    rng = request.args.get("range", "today")
    group = request.args.get("group", "")
    start, end, key = range_bounds(rng)

    where = ["ts BETWEEN ? AND ?", "campaign = ?"]
    params = [start, end, name]
    if group and group != "All Groups":
        where.append("group_name = ?")
        params.append(group)
    wsql = " AND ".join(where)

    with _db_lock, db() as c:
        rows = c.execute(
            f"SELECT user_id,event_type,campaign,link_url,approval,ts "
            f"FROM events WHERE {wsql}", params).fetchall()
        # exits is campaign ke links pe hue (exit event me campaign blank hota
        # hai, isliye alag se nahi jodte — link-level exits approx hai)

    joins = sum(1 for r in rows if r["event_type"] == "join")
    exits = sum(1 for r in rows if r["event_type"] == "exit")
    unique = len({r["user_id"] for r in rows if r["event_type"] == "join"})
    last = max([r["ts"] for r in rows if r["event_type"] == "join"], default=0)

    # per-link breakdown
    links = {}
    for r in rows:
        url = r["link_url"] or "(no link)"
        if url == "(no link)" and r["event_type"] == "exit":
            continue
        lk = links.setdefault(url, {"url": url, "name": r["campaign"],
                                    "approval": bool(r["approval"]),
                                    "joins": 0, "exits": 0})
        if r["event_type"] == "join":
            lk["joins"] += 1
            if r["approval"]:
                lk["approval"] = True
        else:
            lk["exits"] += 1
    link_list = sorted(links.values(), key=lambda x: x["joins"], reverse=True)

    return jsonify({
        "name": name,
        "joins": joins, "unique": unique, "exits": exits,
        "last_full": full_date(last), "last_ago": ago(last),
        "links": link_list
    })


def full_date(ts):
    if not ts:
        return "-"
    d = datetime.datetime.fromtimestamp(ts, IST)
    return d.strftime("%-d %b %Y, %-I:%M %p")


def ago(ts):
    if not ts:
        return "-"
    mins = int((time.time() - ts) / 60)
    if mins < 1:
        return "Just now"
    if mins < 60:
        return f"{mins}m ago"
    h = mins // 60
    if h < 24:
        return f"{h}h ago"
    return f"{h // 24}d ago"


def build_chart(rows, key):
    """Join/Exit ko time buckets me daalta hai."""
    now = datetime.datetime.now(IST)
    if key in ("today", "yesterday"):
        base = last_8pm(now) if key == "today" else \
            last_8pm(now) - datetime.timedelta(days=1)
        buckets = [base + datetime.timedelta(hours=2 * i) for i in range(12)]
        labels = [b.strftime("%I%p").lstrip("0") for b in buckets]
        step = 2 * 3600
    else:
        days = 7 if key == "7days" else 30
        start = (now - datetime.timedelta(days=days)).replace(
            hour=0, minute=0, second=0, microsecond=0)
        n = min(days, 15)
        gap = max(1, days // n)
        buckets = [start + datetime.timedelta(days=gap * i) for i in range(n)]
        labels = [b.strftime("%d %b") for b in buckets]
        step = gap * 86400
    edges = [int(b.timestamp()) for b in buckets]
    j = [0] * len(edges)
    e = [0] * len(edges)
    for r in rows:
        for i, edge in enumerate(edges):
            if edge <= r["ts"] < edge + step:
                if r["event_type"] == "join":
                    j[i] += 1
                else:
                    e[i] += 1
                break
    return labels, j, e


